import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        String line1 = br.readLine();
        String line2 = br.readLine();
        int n = Integer.parseInt(line1);
        String text = line2 + "_";

        boolean inParen = false, inWord = false;
        int countWords = 0, lengthCurrentWord = 0, maxWordLength = 0;

        for (int i = 0; i <= n; i++) {
            char c = text.charAt(i);
            if (inWord && (c == '_' || c == '(' || c == ')')) {
                inWord = false;
                if (inParen) {
                    countWords++;
                } else if (lengthCurrentWord > maxWordLength) {
                    maxWordLength = lengthCurrentWord;
                }
                if (c == '(') {
                    inParen = true;
                }
                if (c == ')') {
                    inParen = false;
                }
                lengthCurrentWord = 0;
            } else if (!inWord && !(c == '_' || c == '(' || c == ')')) {
                inWord = true;
                lengthCurrentWord++;
            } else if (inWord) {
                lengthCurrentWord++;
            } else {
                if (c == '(') {
                    inParen = true;
                } else if (c == ')') {
                    inParen = false;
                }
            }
        }
        pw.printf("%d %d", maxWordLength, countWords);
        pw.close();
    }
}
